import Image from "next/image";
import Link from "next/link";
import type { ReactNode } from "react";
import { WORDMARK } from "@/content/home/chrome";

/**
 * Brand guide v1 lockups (extracted from NEWMA_GUIDE_V1.pdf, regenerated by scripts/build-brand-icons.mjs),
 * cropped to their ink. `wordmark` is newma™ alone, for tight spaces such as the header (minimum 96px
 * wide); `logo` adds the "AI-Powered Ethnobotanical Drug Discovery" tagline (minimum 180px wide).
 * `light` is the primary gradient colourway for white grounds; `dark` is the white one for Forest.
 * Never recolour a lockup with filters: each ground has its own file.
 */
const LOCKUPS = {
  wordmark: {
    light: "/brand/newma-wordmark.svg",
    dark: "/brand/newma-wordmark-reversed.svg",
    width: 1456,
    height: 288,
  },
  logo: {
    light: "/brand/newma-logo.svg",
    dark: "/brand/newma-logo-reversed.svg",
    width: 2074,
    height: 288,
  },
} as const;

type WordmarkProps = {
  href?: string;
  label?: string;
  lockup?: keyof typeof LOCKUPS;
  /** `adaptive` ships both colourways; CSS swaps on `[data-tone="dark"]` or `html[data-theme="dark"]`. */
  tone?: "light" | "dark" | "adaptive";
  /** Size classes. Set a height; the width follows the lockup's ratio. */
  imageClassName?: string;
  priority?: boolean;
  /** Names the lockup for a cross-route view transition. Only one instance may opt in. */
  viewTransition?: boolean;
  children?: ReactNode;
};

// The image is decorative: the link name is the accessible label.
export function Wordmark({
  href = "/",
  label = WORDMARK.homeLabel.text,
  lockup = "wordmark",
  tone = "light",
  imageClassName = "h-6 w-auto sm:h-7",
  priority = false,
  viewTransition = false,
  children,
}: WordmarkProps) {
  const art = LOCKUPS[lockup];
  const image = (colourway: "light" | "dark", className = imageClassName, standby = false) => (
    <Image
      src={art[colourway]}
      alt=""
      width={art.width}
      height={art.height}
      priority={standby ? false : priority}
      // The hidden colourway of a priority (above-the-fold) adaptive lockup loads eagerly at low
      // priority: a lazy image under display:none is not fetched until shown, which would leave a blank
      // slot on the first swap. A lockup below the fold stays lazy in both colourways, so neither is
      // fetched before first paint.
      loading={standby && priority ? "eager" : undefined}
      fetchPriority={standby && priority ? "low" : undefined}
      className={className}
    />
  );
  return (
    <Link
      href={href}
      aria-label={label}
      className="inline-flex min-h-11 min-w-0 items-center gap-2"
    >
      <span
        className="inline-flex"
        style={viewTransition ? { viewTransitionName: "wordmark" } : undefined}
      >
        {tone === "adaptive" ? (
          <>
            {image("light", `wordmark-light ${imageClassName}`)}
            {image("dark", `wordmark-dark ${imageClassName}`, true)}
          </>
        ) : (
          image(tone)
        )}
      </span>
      {children}
    </Link>
  );
}
